const $=s=>document.querySelector(s);let index=0,lang='zh';let saved=[],notes={};try{saved=JSON.parse(localStorage.getItem('sprachraum-saved')||'[]');notes=JSON.parse(localStorage.getItem('sprachraum-notes')||'{}');if(!Array.isArray(saved))saved=[];if(!notes||typeof notes!=='object'||Array.isArray(notes))notes={}}catch{}const q=()=>QUOTES[index];let toastTimer;let topic='all',randomBag=[];const pool=()=>QUOTES.map((a,i)=>i).filter(i=>topic==='all'||QUOTES[i].topic===topic);
function toast(t){$('#toast').textContent=t;$('#toast').style.opacity=1;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.opacity=0,2200)}
function persist(){try{localStorage.setItem('sprachraum-saved',JSON.stringify(saved));localStorage.setItem('sprachraum-notes',JSON.stringify(notes))}catch{toast('浏览器未允许保存；本次阅读仍可继续')}}
function blend(){const v=Number($('#depth').value)/100;$('#ghost').style.opacity=v*.65;$('#ghost').style.transform=`translateX(${(1-v)*25}px)`;$('#quote').style.opacity=1-v*.72;$('#quote').style.transform=`translateX(${-v*12}px)`}
function render(){const a=q();$('#quote').textContent=a[lang];$('#edition').textContent=EDITIONS[lang].short;$('#quote').lang=lang==='zh'?'zh-CN':lang;$('#ghost').textContent=a[lang==='de'?'en':'de'];$('#number').textContent=a.id;$('#theme').textContent=a.theme;const indices=pool();$('#position').textContent=`${String(indices.indexOf(index)+1).padStart(2,'0')} / ${String(indices.length).padStart(2,'0')}`;$('#card-scroll-hint').hidden=true;requestAnimationFrame(fitQuote);$('#save').textContent=saved.includes(a.id)?'✓ 已收藏':'＋ 收藏这一句';$('#count').textContent=saved.length;$('#depth').value=0;blend();document.querySelectorAll('[data-lang]').forEach(b=>{b.classList.toggle('active',b.dataset.lang===lang);b.setAttribute('aria-pressed',b.dataset.lang===lang)})}
function fitQuote(){const el=$('#quote'),frame=$('.frame');el.style.fontSize='';const base=parseFloat(getComputedStyle(el).fontSize);const available=frame.clientHeight-parseFloat(getComputedStyle(frame).paddingTop)-parseFloat(getComputedStyle(frame).paddingBottom);let size=base;el.style.maxHeight='none';while(el.scrollHeight>available&&size>18){size-=1;el.style.fontSize=size+'px'}el.style.maxHeight=Math.max(80,available)+'px';const overflow=el.scrollHeight>el.clientHeight+2;$('#card-scroll-hint').hidden=!overflow;el.tabIndex=overflow?0:-1;el.scrollTop=0}
window.addEventListener('resize',()=>requestAnimationFrame(fitQuote));document.fonts.ready.then(fitQuote);
function move(d){const indices=pool();index=indices[(indices.indexOf(index)+d+indices.length)%indices.length];render()}
$('#topic').onchange=e=>{topic=e.target.value;randomBag=[];const indices=pool();if(!indices.includes(index))index=indices[0];render()};
$('#random').onclick=()=>{const indices=pool();if(indices.length<2)return;randomBag=randomBag.filter(i=>i!==index);if(!randomBag.length){randomBag=indices.filter(i=>i!==index);for(let i=randomBag.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[randomBag[i],randomBag[j]]=[randomBag[j],randomBag[i]]}}let next=randomBag.pop();if(next===index&&randomBag.length)next=randomBag.pop();index=next;render()};
$('#export').onclick=()=>exportCard(q(),lang);$('#next').onclick=()=>move(1);$('#prev').onclick=()=>move(-1);document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{lang=b.dataset.lang;render()});$('#depth').oninput=blend;$('#save').onclick=()=>{const id=q().id;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];persist();render()};const dialog=$('#detail');$('#detail .close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
function context(){const a=q(),body=$('#detailBody');body.replaceChildren();const add=(tag,t,cls)=>{let el=document.createElement(tag);el.textContent=t;if(cls)el.className=cls;body.append(el);return el};add('p','TRACTATUS LOGICO-PHILOSOPHICUS · '+a.id,'meta');add('h2','回到文本');['de','zh','en'].forEach(l=>{const p=add('p',a[l]);p.lang=l});add('h3','文本与译本');['de','zh','en'].forEach(l=>add('p',EDITIONS[l].full,'meta'));const source=add('a','核对 1922 年德英对照版 ↗');source.href='https://en.wikisource.org/wiki/Tractatus_Logico-Philosophicus';source.target='_blank';source.rel='noopener noreferrer';const info=add('a','底本、术语与版权说明 ↗');info.href='./TEXT_SOURCES.md';info.target='_blank';info.rel='noopener noreferrer';add('h3','译注与阅读提示');add('p',a.note);add('p','主题由项目编者归类；本库仅含早期《逻辑哲学论》，不代表维特根斯坦后期立场。','meta');add('p','以上导读与网页动画为本项目创作，不属于原文。','meta');const link=add('a','阅读原文与上下文 ↗');link.href=a.url;link.target='_blank';link.rel='noopener noreferrer';const label=add('label','此刻的理解');label.htmlFor='note';const area=add('textarea','');area.id='note';area.placeholder='给未来的自己留一句话……';area.value=notes[a.id]||'';area.oninput=()=>{notes[a.id]=area.value;persist()};add('p','笔记与收藏仅保存在当前浏览器，不会上传。','meta');dialog.showModal()}
$('#context').onclick=context;$('#library').onclick=()=>{const b=$('#detailBody');b.replaceChildren();const h=document.createElement('h2');h.textContent='留下的句子';b.append(h);if(!saved.length){const p=document.createElement('p');p.textContent='还没有收藏。读到想停留的一句时，点一下收藏。';b.append(p)}QUOTES.filter(a=>saved.includes(a.id)).forEach(a=>{const btn=document.createElement('button');btn.className='entry';btn.textContent=a.id+' / '+a[lang];btn.onclick=()=>{index=QUOTES.indexOf(a);topic='all';$('#topic').value='all';randomBag=[];render();dialog.close()};b.append(btn)});dialog.showModal()};$('#silence').onclick=()=>{document.querySelector('#bgm').pause();$('#blank').hidden=false;$('#blank button').focus()};$('#blank button').onclick=()=>{$('#blank').hidden=true;$('#silence').focus()};document.addEventListener('keydown',e=>{if(!$('#blank').hidden){if(e.key==='Escape')$('#blank button').click();return}if(dialog.open||document.querySelector('#music-dialog').open||['TEXTAREA','INPUT'].includes(e.target.tagName))return;if(e.key==='ArrowRight')move(1);if(e.key==='ArrowLeft')move(-1)});let start;$('.frame').addEventListener('pointerdown',e=>start={x:e.clientX,y:e.clientY});$('.frame').addEventListener('pointerup',e=>{if(start&&Math.abs(e.clientX-start.x)>65&&Math.abs(e.clientY-start.y)<60)move(e.clientX<start.x?1:-1);start=null});$('.frame').addEventListener('pointercancel',()=>start=null);render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
